import * as React from "react";
import "./EmailField.scss";
import { TextField } from "../textField";
import type { TextFieldProps } from "../textField";
import { Verify, type VerifyProps } from "../verify";

export interface EmailFieldProps extends TextFieldProps {
  /**
   * Determines whether to show verification UI component
   */
  enableVerify?: boolean;
  /**
   * Indicates if the email is currently verified
   */
  verified?: boolean;
  /**
   * Custom verification component (overrides default Verify)
   */
  verify?: React.ReactNode;
  /**
   * Props for the default Verify component (excluding 'verified' and 'onClick')
   */
  verifyProps?: Omit<VerifyProps, "verified" | "onClick">;
  /**
   * Callback fired when verification is requested
   */
  onVerify?: () => void;
  /**
   * Supporting text when verification is successful
   */
  verifySuccessText?: string;
}

export const EmailField: React.FC<EmailFieldProps> = ({
  enableVerify = false,
  verified = false,
  verify,
  verifyProps,
  onVerify,
  verifySuccessText = "Successfully Verified",
  type = "email",
  supportingText,
  ...rest
}) => {
  const internalVerify = verify ?? (
    <Verify verified={verified} onClick={onVerify} {...verifyProps} />
  );
  const trailing = enableVerify ? internalVerify : undefined;
  const defaultSupportingText = (
    <div>
      Click <span className="bold-verify">verify</span> to validate your email
      address
    </div>
  );
  const successText = (
    <div className="email-field verified-success">{verifySuccessText}</div>
  );
  const internalSupportingText = verified
    ? successText
    : supportingText ?? defaultSupportingText;
  return (
    <TextField
      trailingIcon={trailing}
      type={type}
      supportingText={internalSupportingText}
      {...rest}
    />
  );
};

export default EmailField;
